import inspect

def has_1pos_and_kwonly(func):
    try:
        sig = inspect.signature(func)
        pos_count = 0
        has_kwonly = False
        for name, param in sig.parameters.items():
            if param.kind == inspect.Parameter.POSITIONAL_ONLY:
                pos_count += 1
            elif param.kind == inspect.Parameter.POSITIONAL_OR_KEYWORD:
                pos_count += 1
            elif param.kind == inspect.Parameter.KEYWORD_ONLY:
                has_kwonly = True
        return pos_count == 1 and has_kwonly
    except (ValueError, TypeError):
        return False

# Test with various functions
def func_with_kwonly(x, *, y):
    return x + y

print('func_with_kwonly:', has_1pos_and_kwonly(func_with_kwonly))

def regular_func(x, y):
    return x + y

